      const fortyEightHoursAgo = new Date(
        Date.now() - 48 * 60 * 60 * 1000,
      ).toISOString();
      const logsToArchive: any[] = [];

      // 1. Get old OOS History
      const oosSnap = await db
        .collection("oos_history")
        .where("timestamp", "<", fortyEightHoursAgo)
